    public function parse_balance($balances): array {
        $timestamp = $this->parse_date($this->safe_string($this->last_response_headers, 'Date'));
        $result = array(
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'info' => $balances,
        );
        for ($i = 0; $i < count($balances); $i++) {
            $balance = $balances[$i];
            $code = $this->safe_currency_code($this->safe_string($balance, 'currency'));
            $lendBorrow = Precise::string_add(
                $this->safe_string($balance, 'lendReserved'),
                $this->safe_string($balance, 'borrowReserved')
            );
            $used = Precise::string_add(
                $lendBorrow,
                $this->safe_string($balance, 'reserved')
            );
            $debt = Precise::string_sub(
                $this->safe_string($balance, 'borrowedAmount'),
                $this->safe_string($balance, 'borrowReserved')
            );
            $result[$code] = array(
                'free' => $this->safe_float($balance, 'available'),
                'used' => $used,
                'total' => $this->safe_float($balance, 'total'),
                'debt' => $debt,
            );
        }
        return $this->safe_balance($result);
    }

