    public function parse_order($order, ?array $market = null): array {
        $orderStatus = $this->safe_string_2($order, 'status', 'orderStatusType');
        $status = null;
        if ($this->in_array($orderStatus, array( 'Placed', 'Active', 'Order Modified', 'Partially Filled' ))) {
            $status = 'open';
        } elseif ($this->in_array($orderStatus, array( 'Failed', 'Cancelled' ))) {
            $failedReason = $this->safe_string($order, 'failedReason');
            if ($this->in_array($failedReason, array( 'Insufficient Balance', 'The borrow amount is unavailable currently, please try again later' ))) {
                $status = 'rejected';
            } else {
                $status = 'canceled';
            }
        } elseif ($orderStatus === 'Filled') {
            $status = 'closed';
        }
        $orderType = $this->safe_string_2($order, 'type', 'orderType');
        $typeParse = null;
        $postOnly = null;
        if ($orderType !== null) {
            if ($orderType === 'market') {
                $typeParse = 'market';
                $postOnly = false;
            } elseif (mb_strpos($orderType, 'limit') !== false) {
                $typeParse = 'limit';
                $postOnly = (mb_strpos($orderType, 'post-only') !== false);
            }
        }
        $totalFee = $this->safe_number_2($order, 'totalFee', 'executedFee');
        $feeCurrency = $this->safe_string($order, 'feeCurrency');
        $fee = null;
        if ($totalFee !== null) {
            $fee = array(
                'cost' => $totalFee,
                'currency' => $this->safe_currency_code($feeCurrency),
                'rate' => null,
            );
        }
        $executedPrice = $this->safe_number($order, 'executedPrice');
        $orderPrice = $this->safe_number_2($order, 'price', 'originalPrice');
        $finalPrice = null;
        if (($executedPrice !== null) && ($executedPrice !== 0)) {
            $finalPrice = $executedPrice;
        } else {
            $finalPrice = $orderPrice;
        }
        $datetime = $this->safe_string_2($order, 'createdAt', 'orderCreatedAt');
        $updateDatetime = $this->safe_string_2($order, 'updatedAt', 'orderUpdatedAt');
        $result = array(
            'id' => $this->safe_string($order, 'orderId'),
            'clientOrderId' => $this->safe_string($order, 'customerOrderId'),
            'timestamp' => $this->parse8601($datetime),
            'datetime' => $datetime,
            'symbol' => $this->safe_symbol($this->safe_string($order, 'currencyPair')),
            'type' => $typeParse,
            'side' => $this->safe_string_2($order, 'side', 'orderSide'),
            'lastTradeTimestamp' => null,
            'lastUpdateTimestamp' => $this->parse8601($updateDatetime),
            'price' => $finalPrice,
            'amount' => $this->safe_string_2($order, 'executedQuantity', 'originalQuantity'),
            'cost' => $this->safe_string($order, 'total'),
            'average' => $this->safe_string($order, 'averagePrice'),
            'filled' => $this->safe_string($order, 'totalExecutedQuantity'),
            'remaining' => $this->safe_string($order, 'remainingQuantity'),
            'timeInForce' => $this->safe_string($order, 'timeInForce'),
            'postOnly' => $postOnly,
            'trades' => null,
            'reduceOnly' => $this->safe_value($order, 'reduceOnly'),
            'triggerPrice' => null,
            'takeProfitPrice' => null,
            'stopLossPrice' => null,
            'status' => $status,
            'fee' => $fee,
            'info' => $order,
        );
        return $this->safe_order($result, $market);
    }

    public function create_order(string $symbol, string $type, string $side, float $amount, ?float $price = null, $params = array ()): array {
        /**
         * @see https://docs.valr.com/#5beb7328-24ca-4d8a-84f2-6029725ad923
         * Create a trade order
         * @param {string} $symbol unified $symbol of the market to create an order in
         * @param {string} $type 'market' or 'limit'
         * @param {string} $side 'buy' or 'sell'
         * @param {float} $amount how much of currency you want to trade in units of base currency
         * @param {float} [$price] the $price at which the order is to be fullfilled, in units of the quote currency. If included in market order, use quote $amount
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {array} [$params->postOnly] if true will place a limit order and fail if matched immidiately
         * @param {array} [$params->clientOrderId] an optional field which can be specified by clients to track this order using their own internal order management systems
         * @param {array} [$params->allowMargin] Set to true for a margin / leverage trade
         * @return {array} an ~@link https://docs.ccxt.com/#/?id=order-structure order structure~ with only the id and $symbol added
         */
        $this->load_markets();
        $response = null;
        $this->check_required_symbol_argument('createOrder', $symbol);
        $marketId = $this->market_id($symbol);
        if ($side !== 'buy' && $side !== 'sell') {
            throw new InvalidOrder($this->id . ' createOrder() - "side" must be either "buy" or "sell".');
        }
        $body = array(
            'side' => strtoupper($side),
            'pair' => $marketId,
        );
        // Optional parameters
        if ($this->safe_string($params, 'clientOrderId')) {
            $body['customerOrderId'] = $this->safe_string($params, 'clientOrderId');
        }
        if ($this->safe_string($params, 'allowMargin')) {
            $body['allowMargin'] = $this->safe_string($params, 'allowMargin');
        }
        $this->omit($params, array( 'allowMargin', 'clientOrderId' ));
        if ($type === 'market') {
            if ($price) {
                $body['quoteAmount'] = $amount;
            } else {
                $body['baseAmount'] = $amount;
            }
            $this->omit($params, array( 'baseAmount', 'quoteAmount' ));
            $response = $this->privatePostOrdersMarket ($this->extend($body, $params));
        } elseif ($type === 'limit') {
            $body['price'] = $this->number_to_string($price);
            $body['quantity'] = $this->number_to_string($amount);
            if ($this->safe_string($params, 'postOnly')) {
                $body['postOnly'] = $this->safe_bool($params, 'postOnly');
                $this->omit($params, 'postOnly');
            }
            $response = $this->privatePostOrdersLimit ($this->extend($body, $params));
        } else {
            throw new InvalidOrder($this->id . ' createOrder() - "type" must be either "market" or "limit" to create an order.');
        }
        $timestamp = $this->parse_date($this->safe_string($this->last_response_headers, 'Date'));
        return $this->parse_order(array(
            'createdAt' => $this->iso8601($timestamp),
            'orderId' => $this->safe_string($response, 'id'),
            'currencyPair' => $marketId,
            'customerOrderId' => $this->safe_string($params, 'clientOrderId'),
        ));
    }

