    public function edit_order(string $id, string $symbol, string $type, string $side, ?float $amount = null, ?float $price = null, $params = array ()): array {
        /**
         * @see https://docs.valr.com/#0d31c914-0393-463b-966a-97dbc50554fd
         * Edit a trade order
         * @param {string} $id order $id
         * @param {string} $symbol unified $symbol of the market to create an order in
         * @param {string} $type 'market' or 'limit'
         * @param {string} $side 'buy' or 'sell'
         * @param {float} [$amount] how much of currency you want to trade in units of base currency
         * @param {float} [$price] the $price at which the order is to be fullfilled, in units of the quote currency. If included in market order, use quote $amount
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->matchRetain] RETAIN_ORIGINAL (default) keeps original order, CANCEL_ORIGINAL to cancle original order or REPRICE to reprice within one tick
         * @param {boolean} [$params->setTotal] If true (default), new $amount will takes current fill quantity into account, otherwise it simply forces new $amount to be set.
         * @param {array} [$params->clientOrderId] an optional field which can be specified by clients to track this order using their own internal order management systems
         * @return {array} an ~@link https://docs.ccxt.com/#/?$id=order-structure order structure~ with only the $id and $symbol added
         */
        $this->load_markets();
        $marketId = $this->market_id($symbol);
        $modifyMethod = $this->safe_string($params, 'matchRetain', 'RETAIN_ORIGINAL');
        $orderFormat = array(
            'orderId' => $id,
            'pair' => $marketId,
            'modifyMatchStrategy' => $modifyMethod,
        );
        if ($price !== null) {
            $orderFormat['newPrice'] = $this->number_to_string($price);
        }
        if ($amount !== null) {
            $amountStrategy = $this->safe_bool($params, 'setTotal', true);
            $amountMethod = ($amountStrategy) ? 'newTotalQuantity' : 'newRemainingQuantity';
            $orderFormat[$amountMethod] = $this->number_to_string($amount);
        }
        if ($this->safe_string($params, 'clientOrderId')) {
            $orderFormat['customerOrderId'] = $this->safe_string($params, 'clientOrderId');
        }
        $params = $this->omit($params, array( 'matchRetain', 'setTotal', 'clientOrderId' ));
        $response = $this->privatePutOrdersModify ($this->extend($orderFormat, $params));
        return $this->parse_order(array(
            'orderUpdatedAt' => $this->iso8601($this->parse_date($this->safe_string($this->last_response_headers, 'Date'))),
            'orderId' => $id,
            'transactionId' => $this->safe_string($response, 'id'),
            'currencyPair' => $marketId,
            'customerOrderId' => $this->safe_string($params, 'clientOrderId'),
        ));
    }

    public function cancel_order(string $id, ?string $symbol = null, $params = array ()): array {
        /**
         * @see https://docs.valr.com/#3d9ba169-7222-4c0f-ab08-87c22162c0c4
         * cancels an open order
         * @param {string} $id order $id or customer order $id
         * @param {string} $symbol unified $symbol of the market the order was made in
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {boolean} [$params->clientOrderId] ID is for clientOrderId field and associate API call (default is false)
         * @return {array} an ~@link https://docs.ccxt.com/#/?$id=order-structure order structure~ with only the $id and $symbol added
         */
        $this->load_markets();
        $this->check_required_symbol_argument('cancelOrder', $symbol);
        $useClientOrderId = $this->safe_bool($params, 'clientOrderId', false);
        $marketId = $this->market_id($symbol);
        $orderFormat = array( 'pair' => $marketId );
        if ($useClientOrderId) {
            $params = $this->omit($params, 'clientOrderId');
            $orderFormat['customerOrderId'] = $id;
        } else {
            $orderFormat['orderId'] = $id;
        }
        $this->privateDeleteOrdersOrder ($this->extend($orderFormat, $params));
        return $this->parse_order(array(
            'orderUpdatedAt' => $this->iso8601($this->parse_date($this->safe_string($this->last_response_headers, 'Date'))),
            'orderId' => (!$useClientOrderId) ? $id : null,
            'customerOrderId' => ($useClientOrderId) ? $id : null,
            'currencyPair' => $marketId,
        ));
    }

    public function cancel_all_orders(?string $symbol = null, $params = array ()): array {
        /**
         * @see https://docs.valr.com/#90822956-7e25-48a8-bd14-a83fb8766b46
         * cancels all an open order or all open orders on a specific market
         * @param {string} [$symbol] unified $symbol of the market the order was made in
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} an list of ~@link https://docs.ccxt.com/#/?id=order-structure order structure~ with only the id and option $symbol added
         */
        $this->load_markets();
        $response = null;
        $marketId = null;
        if ($symbol === null) {
            $response = $this->privateDeleteOrders ($params);
        } else {
            $this->check_required_symbol_argument('cancelAllOrders', $symbol);
            $marketId = $this->market_id($symbol);
            $body = array(
                'pair' => $marketId,
            );
            $response = $this->privateDeleteOrdersPair ($this->extend($body, $params));
        }
        $timestamp = $this->parse_date($this->safe_string($this->last_response_headers, 'Date'));
        for ($i = 0; $i < count($response); $i++) {
            $response[$i]['currencyPair'] = $marketId;
            $response[$i]['orderUpdatedAt'] = $this->iso8601($timestamp);
        }
        return $this->parse_orders($response);
    }

