    public function fetch_ledger(?string $code = null, ?int $since = null, ?int $limit = null, $params = array ()) {
        /**
         * @see https://docs.valr.com/#0d7cc0ff-b8ca-4e1f-980e-36d07672e53d
         * fetch the history of changes, actions done by the user or operations that altered balance of the user
         * @param {string} [$code] uunified $currency $code, default is null
         * @param {int} [$since] timestamp in ms of the earliest ledger entry, default is null
         * @param {int} [$limit] max number of ledger entrys to return, default is null
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {array} [$params->skip] number of items to skip from list
         * @param {array} [$params->transactionTypes] string list of transaction types to match (see VALR docs for details)
         * @return {array} a list of {@link https://github.com/ccxt/ccxt/wiki/Manual#ledger-entry-structure ledger entry structure}
         */
        $this->load_markets();
        $currency = null;
        $queryParams = array();
        if ($code !== null) {
            $currency = $this->currency($code);
            $queryParams['currency'] = $currency['id'];
        }
        if ($since !== null) {
            $queryParams['startTime'] = $this->iso8601($since);
        }
        if ($limit !== null) {
            $queryParams['limit'] = $limit;
        }
        $response = $this->privateGetAccountTransactionhistory ($this->extend($queryParams, $params));
        $params = $this->omit($params, 'transactionTypes');
        $accountId = array(
            'account' => $this->safe_string($this->last_request_headers, 'X-VALR-SUB-ACCOUNT-ID', '0'),
        );
        return $this->parse_ledger($response, $currency, $since, $limit, $this->extend($accountId, $params));
    }

    public function parse_ledger_entry($item, ?array $currency = null): array {
        $ledgerTypeInfo = $this->safe_dict($item, 'transactionType');
        $ledgerType = $this->safe_string($ledgerTypeInfo, 'type');
        $transactionTypes = array(
            'ACCOUNT_FUNDING' => array( 'deposit', 'in' ),
            'LIMIT_BUY' => array( 'trade', 'in' ),
            'LIMIT_SELL' => array( 'trade', 'out' ),
            'MARKET_BUY' => array( 'trade', 'in' ),
            'MARKET_SELL' => array( 'trade', 'out' ),
            'SIMPLE_BUY' => array( 'trade', 'in' ),
            'SIMPLE_SELL' => array( 'trade', 'out' ),
            'AUTO_BUY' => array( 'trade', 'in' ),
            'MAKER_REWARD' => array( 'cashback', 'in' ),
            'BLOCKCHAIN_RECEIVE' => array( 'deposit', 'in' ),
            'BLOCKCHAIN_SEND' => array( 'withdrawal', 'out' ),
            'FIAT_DEPOSIT' => array( 'deposit', 'in' ),
            'FIAT_WITHDRAWAL' => array( 'withdrawal', 'out' ),
            'REFERRAL_REBATE' => array( 'rebate', 'in' ),
            'REFERRAL_REWARD' => array( 'referral', 'in' ),
            'PROMOTIONAL_REBATE' => array( 'rebate', 'in' ),
            'INTERNAL_TRANSFER' => array( 'transfer', null ),
            'FIAT_WITHDRAWAL_REVERSAL' => array( 'deposit', 'in' ),
            'PAYMENT_SENT' => array( 'withdrawal', 'out' ),
            'PAYMENT_RECEIVED' => array( 'deposit', 'in' ),
            'PAYMENT_REVERSED' => array( 'deposit', 'in' ),
            'PAYMENT_REWARD' => array( 'cashback', 'in' ),
            'OFF_CHAIN_BLOCKCHAIN_WITHDRAW' => array( 'withdrawal', 'out' ),
            'OFF_CHAIN_BLOCKCHAIN_DEPOSIT' => array( 'deposit', 'in' ),
            'SIMPLE_SWAP_BUY' => array( 'trade', 'in' ),
            'SIMPLE_SWAP_SELL' => array( 'trade', 'out' ),
            'SIMPLE_SWAP_FAILURE_REVERSAL' => array( 'transaction', null ),
            'SPOT_LEND_INTEREST_PAYMENT' => array( 'interest', 'in' ),
            'SPOT_BORROW_INTEREST_CHARGE' => array( 'interest', 'out' ),
            'FUTURES_FUNDING_PAID' => array( 'interest', 'out' ),
            'FUTURES_PNL_LOSS' => array( 'trade', 'out' ),
            'FUTURES_PNL_PROFIT' => array( 'trade', 'in' ),
        );
        // $transactionDisciption = $this->safe_string(transactionTypeInfo, 'Deposit');
        $entryTime = $this->parse_date($this->safe_string($item, 'eventAt'));
        $additionalInfo = $this->safe_dict($item, 'additionalInfo');
        $matchEventType = $this->safe_list($transactionTypes, $ledgerType);
        $parseType = null;
        $direction = null;
        if ($matchEventType !== null) {
            $parseType = $matchEventType[0];
            $direction = $matchEventType[1];
        } else {
            $this->log($ledgerType);
        }
        if ($ledgerType === 'INTERNAL_TRANSFER') {
            $direction = (is_array($item) && array_key_exists('creditCurrency', $item)) ? 'in' : 'out';
        }
        $amount = null;
        $code = null;
        if ($direction === 'in') {
            $amount = $this->safe_number($item, 'creditValue');
            $code = $this->safe_currency_code($this->safe_string($item, 'creditCurrency'));
        } elseif ($direction === 'out') {
            $amount = $this->safe_number($item, 'debitValue');
            $code = $this->safe_currency_code($this->safe_string($item, 'debitCurrency'));
        }
        return array(
            'id' => $this->safe_string($item, 'id'),
            'timestamp' => $entryTime,
            'datetime' => $this->iso8601($entryTime),
            'direction' => $direction,
            'account' => null,
            'referenceId' => $this->safe_string_2($additionalInfo, 'sourceTransactionId', 'orderId'),
            'referenceAccount' => null,
            'type' => $parseType,
            'currency' => $code,
            'amount' => $amount,
            'before' => 0,
            'after' => 0,
            'status' => 'ok',
            'fee' => array(
                'currency' => $this->safe_currency_code($this->safe_string($item, 'feeCurrency')),
                'cost' => $this->safe_number($item, 'feeValue'),
                'rate' => null,
            ),
            'info' => $item,
        );
    }

    public function withdraw(string $code, float $amount, string $address, ?string $tag = null, $params = array ()): array {
        /**
         * @see https://docs.valr.com/#bb0ad4dc-a28d-41a3-8e59-5070bc589c5a
         * @see https://docs.valr.com/#fb4db187-530b-4632-b933-7bdfd192bcf5
         * make a withdrawal
         * @param {string} $code unified $currency $code
         * @param {float} $amount the $amount to withdraw
         * @param {string} $address the $address to withdraw to
         * @param {string} $tag
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/#/?id=transaction-structure transaction structure~
         */
        $this->load_markets();
        $this->check_required_currency_code_argument('fetchWithdrawals', $code);
        $currency = $this->safe_currency($code);
        // todo => Include 'networkType' from default $currency if none provided via $params
        $response = null;
        if ($this->is_fiat($code)) {
            $withdrawalBody = array(
                'currency' => $currency['id'],
                'linkedBankAccountId' => $address,
                'amount' => $this->number_to_string($amount),
            );
            $response = $this->privatePostWalletFiatCurrencyWithdraw ($this->extend($withdrawalBody, $params));
        } else {
            $withdrawalBody = array(
                'currency' => $currency['id'],
                'address' => $address,
                'amount' => $this->number_to_string($amount),
            );
            $response = $this->privatePostWalletCryptoCurrencyWithdraw ($this->extend($withdrawalBody, $params));
        }
        return $this->parse_transaction($response);
    }

    public function parse_transaction($transaction, ?array $currency = null): array {
        if (is_array($transaction) && array_key_exists('transactionType', $transaction)) {
            return $this->parse_transaction_history($transaction);
        }
        $timestamp = $this->parse8601($this->safe_string($transaction, 'createdAt'));
        $code = $this->safe_currency_code($this->safe_string($transaction, 'currencyCode'));
        $status = null;
        if ($this->safe_bool($transaction, 'confirmed')) {
            $status = 'ok';
        }
        $transactionType = null;
        if (is_array($transaction) && array_key_exists('receiveAddress', $transaction)) {
            $transactionType = 'deposit';
        }
        return array(
            'info' => $transaction,
            'id' => $this->safe_string($transaction, 'id'),
            'txid' => $this->safe_string($transaction, 'transactionHash'),
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'address' => $this->safe_string($transaction, 'receiveAddress'),
            'addressFrom' => null,
            'addressTo' => null,
            'tag' => null,
            'tagFrom' => null,
            'tagTo' => null,
            'type' => $transactionType,
            'amount' => $this->safe_number($transaction, 'amount'),
            'currency' => $code,
            'status' => $status,
            'updated' => $this->parse8601($this->safe_string($transaction, 'confirmedAt')),
            'fee' => null,
            'network' => $this->safe_string($transaction, 'networkType'),
            'comment' => null,
            'internal' => null,
        );
    }

    public function parse_transaction_history($transaction) {
        $transactionTypeInfo = $this->safe_dict($transaction, 'transactionType');
        $transactionType = $this->safe_string($transactionTypeInfo, 'type');
        // $transactionDisciption = $this->safe_string($transactionTypeInfo, 'Deposit');
        $parseType = null;
        $amount = null;
        $status = null;
        $currency = null;
        $address = null;
        $addressTo = null;
        $fee = null;
        $eventTime = $this->parse_date($this->safe_string($transaction, 'eventAt'));
        if ($transactionType === 'FIAT_DEPOSIT' || $transactionType === 'FIAT_WITHDRAWAL') {
            $parseType = ($transactionType === 'FIAT_DEPOSIT') ? 'deposit' : 'withdrawal';
            $amount = $this->safe_number_2($transaction, 'creditValue', 'debitValue');
            $status = 'ok';
            $currency = $this->safe_currency_code($this->safe_string_2($transaction, 'creditCurrency', 'debitCurrency'));
            $fee = array(
                'currency' => $this->safe_currency_code($this->safe_string($transaction, 'feeCurrency')),
                'cost' => $this->safe_number($transaction, 'feeValue'),
                'rate' => null,
            );
            if ($parseType === 'withdrawal') {
                $additionalInfo = $this->safe_dict($transaction, 'additionalInfo');
                $address = $this->safe_string($additionalInfo, 'accountNumber');
                $addressTo = $this->safe_string($additionalInfo, 'bankName');
            }
        }
        return array(
            'info' => $transaction,
            'id' => $this->safe_string($transaction, 'id'),
            'txid' => null,
            'timestamp' => $eventTime,
            'datetime' => $this->iso8601($eventTime),
            'address' => $address,
            'addressFrom' => null,
            'addressTo' => $addressTo,
            'tag' => null,
            'tagFrom' => null,
            'tagTo' => null,
            'type' => $parseType,
            'amount' => $amount,
            'currency' => $currency,
            'status' => $status,
            'updated' => null,
            'fee' => $fee,
            'network' => null,
            'comment' => null,
            'internal' => null,
        );
    }

    public function fetch_cross_borrow_rates($params = array ()): CrossBorrowRates {
        $this->load_markets();
        $response = $this->privateGetLoansRates ($params);
        $results = array();
        for ($i = 0; $i < count($response); $i++) {
            $borrowRate = $response[$i];
            $code = $this->safe_currency_code($this->safe_string($borrowRate, 'currency'));
            if ($code !== null) {
                $results[$code] = $this->parse_borrow_rate($borrowRate);
            }
        }
        return $results;
    }

    public function parse_borrow_rate($info, ?array $currency = null): array {
        $code = $this->safe_currency_code($this->safe_string($info, 'currency'));
        $httpTime = $this->safe_string($this->last_response_headers, 'Date');
        $timestamp = $this->parse_date($httpTime);
        return array(
            'currency' => $code,
            'rate' => $this->safe_float($info, 'estimatedNextBorrowRate'),
            'period' => 3600000,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'info' => $info,
        );
    }

