    public function parse_borrow_interest($info, ?array $market = null) {
        $code = $this->safe_currency_code($this->safe_string($info, 'currency'));
        $amount = $this->safe_string($info, 'quantity');
        $interestAmount = $this->safe_string($info, 'interestAmount');
        $interestRate = Precise::string_div($interestAmount, $amount, 9);
        return array(
            'account' => null,
            'currency' => $code,
            'interest' => $this->parse_number($interestAmount),
            'interestRate' => $this->parse_number($interestRate),
            'amountBorrowed' => $this->parse_number($amount),
            'timestamp' => $this->parse_date($this->safe_string($info, 'createdAt')),
            'datetime' => $this->safe_string($info, 'createdAt'),
            'info' => $info,
        );
    }

    public function transfer(string $code, float $amount, string $fromAccount, string $toAccount, $params = array ()): array {
        $this->load_markets();
        $this->load_accounts();
        $currency = $this->safe_currency($code);
        $accountsByName = $this->index_by($this->accounts, 'name');
        $fromAccountId = $this->safe_dict($accountsByName, $fromAccount);
        $toAccountId = $this->safe_dict($accountsByName, $toAccount);
        $query = array(
            'fromId' => $fromAccountId ? $fromAccountId['id'] : $fromAccount,
            'toId' => $toAccountId ? $toAccountId['id'] : $toAccount,
            'currencyCode' => $currency['id'],
            'amount' => $amount,
            'subAccountId' => '0',
        );
        $this->privatePostAccountSubaccountsTransfer (($this->extend($query, $params)));
        $responseTimestamp = $this->parse_date($this->safe_string($this->last_response_headers, 'Date'));
        $last_json_request = $this->parse_json($this->last_request_body);
        $requestedCurrency = $this->safe_string($last_json_request, 'currencyCode');
        return array(
            'info' => null,
            'id' => null,
            'timestamp' => $responseTimestamp,
            'datetime' => $this->iso8601($responseTimestamp),
            'currency' => $this->safe_currency_code($requestedCurrency),
            'amount' => $this->safe_number($last_json_request, 'amount'),
            'fromAccount' => $this->safe_string($last_json_request, 'fromId'),
            'toAccount' => $this->safe_string($last_json_request, 'toId'),
            'status' => null,
        );
    }

    public function fetch_transfers(?string $code = null, ?int $since = null, ?int $limit = null, $params = array ()): array {
        /**
         * fetches a transfer
         * @param {string} id transfer id
         * @param {int} [$since] timestamp in ms of the earliest transfer to fetch
         * @param {int} [$limit] the maximum amount of transfers to fetch
         * @param {array} $params extra parameters specific to the exchange api endpoint
         * @return {array} a ~@link https://docs.ccxt.com/#/?id=transfer-structure transfer structure~
         */
        $this->load_markets();
        $this->load_accounts();
        $query = array(
            'transactionTypes' => 'INTERNAL_TRANSFER',
        );
        $currency = $this->safe_currency($code);
        if ($code !== null) {
            $query['currency'] = $currency['id'];
        }
        if ($since !== null) {
            $query['startTime'] = $this->iso8601($since);
        }
        if ($limit !== null) {
            $query['limit'] = $limit;
        }
        $response = $this->privateGetAccountTransactionhistory ($this->extend($query, $params));
        return $this->parse_transfers($response, $currency, $since, $limit, $params);
    }

    public function parse_transfer(array $transfer, ?array $currency = null): array {
        // [array('transactionType' => array('type' => 'INTERNAL_TRANSFER', 'description' => 'Transfer'),
        //     'debitCurrency' => 'ZAR',
        //     'debitValue' => '1',
        //     'eventAt' => '2024-06-13T20:49:36.846Z',
        //     'additionalInfo' => array('reason' => 'SUB_ACCOUNT',
        //      'reasonDescription' => 'Transfer between subaccounts',
        //      'additional' => 'Transfer from Primary to Development'),
        //     'id' => '723a6e23-29c6-11ef-9e76-33277cfdd873'),
        //    array('transactionType' => {'type' => 'INTERNAL_TRANSFER', 'description' => 'Transfer'),
        //     'creditCurrency' => 'ZAR',
        //     'creditValue' => '62629.65',
        //     'eventAt' => '2024-06-12T05:19:28.689Z',
        //     'additionalInfo' => array('reason' => 'SUB_ACCOUNT',
        //      'reasonDescription' => 'Transfer between subaccounts',
        //      'additional' => 'Transfer from Trading to Primary'),]
        $ledgerTypeInfo = $this->safe_dict($transfer, 'transactionType');
        $ledgerType = $this->safe_string($ledgerTypeInfo, 'type');
        $transactionTypes = array(
            'INTERNAL_TRANSFER' => array( 'transfer', null ),
            // 'PAYMENT_SENT' => array( 'withdrawal', 'out' ),
            // 'PAYMENT_RECEIVED' => array( 'deposit', 'in' ),
            // 'PAYMENT_REVERSED' => array( 'deposit', 'in' ),
            // 'PAYMENT_REWARD' => array( 'cashback', 'in' ),
        );
        // $transactionDisciption = $this->safe_string(transactionTypeInfo, 'Deposit');
        $entryTime = $this->parse_date($this->safe_string($transfer, 'eventAt'));
        $additionalInfo = $this->safe_dict($transfer, 'additionalInfo');
        $matchEventType = $this->safe_list($transactionTypes, $ledgerType);
        // $parseType = null;
        $direction = null;
        if ($matchEventType !== null) {
            // $parseType = $matchEventType[0];
            $direction = $matchEventType[1];
        }
        if ($ledgerType === 'INTERNAL_TRANSFER') {
            $direction = (is_array($transfer) && array_key_exists('creditCurrency', $transfer)) ? 'in' : 'out';
        }
        $amount = null;
        $code = null;
        if ($direction === 'in') {
            $amount = $this->safe_number($transfer, 'creditValue');
            $code = $this->safe_currency_code($this->safe_string($transfer, 'creditCurrency'));
        } elseif ($direction === 'out') {
            $amount = $this->safe_number($transfer, 'debitValue');
            $code = $this->safe_currency_code($this->safe_string($transfer, 'debitCurrency'));
        }
        $accounts = $this->safe_string($additionalInfo, 'additional');
        $fromIndex = mb_strpos($accounts, 'from');
        $toIndex = mb_strpos($accounts, 'to');
        $fromAccount = mb_substr($accounts, $fromIndex + 5, $toIndex - 1 - $fromIndex + 5);
        $toAccount = mb_substr($accounts, $toIndex + 3);
        $accountsByName = $this->index_by($this->accounts, 'name');
        $fromAccountId = $this->safe_dict($accountsByName, $fromAccount);
        $toAccountId = $this->safe_dict($accountsByName, $toAccount);
        return array(
            'id' => $this->safe_string($transfer, 'id'),
            'timestamp' => $entryTime,
            'datetime' => $this->iso8601($entryTime),
            'currency' => $code,
            'amount' => $amount,
            'fromAccount' => $fromAccountId ? $fromAccountId['id'] : $fromAccount,
            'toAccount' => $toAccountId ? $toAccountId['id'] : $toAccount,
            'status' => 'ok',
            'info' => $transfer,
        );
    }

    public function fetch_open_interest(string $symbol, $params = array ()): OpenInterest {
        /**
         * @see https://docs.valr.com/#459c7c67-3c0f-494e-851b-2fd83cbff2da
         * fetches information on open interest
         * @param {array} $params extra parameters specific to the exchange api endpoint
         * @return {array} a ~@link https://docs.ccxt.com/#/README?id=open-interest-structure open intrest structure~
         */
        $this->load_markets();
        $response = $this->publicGetFuturesInfo ($params);
        $result = $this->parse_open_interests($response, array( $symbol ));
        return $this->filter_by_symbol($result, $symbol);
    }

    public function parse_open_interest($interest, ?array $market = null): OpenInterest {
        throw new NotSupported($this->id . ' parseOpenInterest () is not supported yet');
    }

    public function fetch_funding_rates(?array $symbols = null, $params = array ()): array {
        /**
         * fetches information on the next funding rate
         * @param {array} $params extra parameters specific to the exchange api endpoint
         * @return {array} a ~@link https://docs.ccxt.com/#/README?id=funding-rate-structure funding rate structure~
         */
        $this->load_markets();
        $response = $this->publicGetFuturesInfo ($params);
        $result = $this->parse_funding_rates($response);
        return $this->filter_by_array($result, 'symbol', $symbols);
    }

    public function parse_funding_rate(string $contract, ?array $market = null): array {
        // {'currencyPair' => 'BTCZARPERP',
        //     'estimatedFundingRate' => '-0.00002',
        //     'openInterest' => '3.3416',
        //     'nextFundingRun' => '1729886400000',
        //     'nextPnlRun' => '1729886400000'}
        $nextFundingTimestamp = $this->safe_integer($contract, 'nextFundingRun');
        return array(
            'symbol' => $this->safe_symbol($this->safe_string($contract, 'currencyPair')),
            'info' => $contract,
            'nextFundingTimestamp' => $nextFundingTimestamp,
            'nextFundingDatetime' => $this->iso8601($nextFundingTimestamp),
            'nextFundingRate' => $this->safe_number($contract, 'estimatedFundingRate'),
            'interval' => '1h',
        );
    }

    public function fetch_positions_for_symbol(string $symbol, $params = array ()): array {
        /**
         * fetches all open positions for specific $symbol, unlike fetchPositions (which is designed to work with multiple symbols) so this method might be preffered for one-market position, because of less rate-limit consumption and speed
         * @param {string} $symbol unified market $symbol
         * @param {array} $params extra parameters specific to the endpoint
         * @param {array} [$params->skip] number of items to skip from list
         * @param {array} [$params->limit] number of items to limit from list
         * @return {array[]} a list of ~@link https://docs.ccxt.com/#/?id=position-structure position structure~ with maximum 3 items - possible one position for "one-way" mode, and possible two positions (long & short) for "two-way" (a.k.a. hedge) mode
         */
        $queryParams = array(
            'currencyPair' => $this->market_id($symbol),
        );
        return $this->fetch_positions($this->extend($queryParams, $params));
    }

    public function fetch_positions(?array $symbols = null, $params = array ()): array {
        $this->load_markets();
        $response = $this->privateGetPositionsOpen ($params);
        return $this->parse_positions($response, $symbols);
    }

    public function parse_position(array $position, ?array $market = null): array {
        // array(
        //     "pair" => "BTCUSDTPERP",
        //     "side" => "buy",
        //     "quantity" => "0.0013",
        //     "realisedPnl" => "15.22299935",
        //     "totalSessionEntryQuantity" => "0.0013",
        //     "totalSessionValue" => "54.2438",
        //     "sessionAverageEntryPrice" => "41726",
        //     "averageEntryPrice" => "30001",
        //     "unrealisedPnl" => "0.2613",
        //     "updatedAt" => "2023-12-05T12:00:00.317Z",
        //     "createdAt" => "2023-11-14T19:41:44.936Z",
        //     "positionId" => "237a9503-b32b-5f40-28a9-03fe7ad510d4"
        //   ),
        $timestamp = $this->parse_date($this->safe_string($position, 'createdAt'));
        $side = $this->safe_string($position, 'side');
        $positionSide = null;
        if ($side === 'buy') {
            $positionSide = 'long';
        } elseif ($side === 'sell') {
            $positionSide = 'short';
        }
        return array(
            'symbol' => $this->safe_symbol($this->safe_string($position, 'pair')),
            'id' => $this->safe_string($position, 'positionId'),
            'info' => $position,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'contracts' => $this->safe_number($position, 'quantity'),
            'contractSize' => $this->safe_number($position, 'totalSessionValue'),
            'side' => $positionSide,
            // notional? => number;
            // leverage? => number;
            'unrealizedPnl' => $this->safe_number($position, 'unrealisedPnl'),
            'realizedPnl' => $this->safe_number($position, 'realisedPnl'),
            // collateral? => number;
            'entryPrice' => $this->safe_number($position, 'averageEntryPrice'),
            // markPrice? => number;
            // liquidationPrice? => number;
            // marginMode? => Str;
            // hedged? => boolean;
            // maintenanceMargin? => number;
            // maintenanceMarginPercentage? => number;
            // initialMargin? => number;
            // initialMarginPercentage? => number;
            // marginRatio? => number;
            // lastUpdateTimestamp? => number;
            // lastPrice? => number;
            // stopLossPrice? => number;
            // takeProfitPrice? => number;
            // percentage? => number;
        );
    }

    public function sign($path, $api = 'public', $method = 'GET', $params = array (), $headers = null, $body = null) {
        $partialPath = $this->implode_params($path, $params);
        $subAccountId = $this->safe_string($params, 'subAccountId');
        $params = $this->omit($params, 'subAccountId');
        if ($subAccountId === '0') {
            $subAccountId = null;
        } elseif ($subAccountId === null) {
            $subAccountId = $this->safe_string($this->options, 'subAccountId');
        }
        $query = $this->omit($params, $this->extract_params($path));
        if ($query) {
            if ($method === 'POST' || $method === 'PUT' || $method === 'DELETE') {
                $body = $this->json($query);
            } else {
                $partialPath .= '?' . $this->urlencode($query);
            }
        }
        $url = $this->urls['api'][$api] . '/' . $partialPath;
        $signHeaders = null;
        if ($api === 'private') {
            $full_path = '/v' . $this->version . '/' . $partialPath;
            $this->check_required_credentials();
            $timestamp = (string) $this->milliseconds();
            $message = $timestamp . strtoupper($method) . $full_path;
            if ($body !== null) {
                $message .= $body;
            }
            if ($subAccountId) {
                $message .= $subAccountId;
            }
            $payloadBase64 = base64_encode($message);
            $signature = $this->hmac(
                base64_decode($payloadBase64),
                base64_decode(base64_encode($this->secret)),
                'sha512',
                'hex'
            );
            $signHeaders = array(
                // 'Content-Type' => 'application/json',
                'X-VALR-API-KEY' => $this->apiKey,
                'X-VALR-SIGNATURE' => $signature,
                'X-VALR-TIMESTAMP' => $timestamp,
            );
            if ($subAccountId) {
                $signHeaders['X-VALR-SUB-ACCOUNT-ID'] = $subAccountId;
            }
        }
        return array( 'url' => $url, 'method' => $method, 'body' => $body, 'headers' => $this->deep_extend($headers, $signHeaders) );
    }

    public function handle_errors(int $statusCode, string $statusText, string $url, string $method, array $responseHeaders, string $responseBody, $response, $requestHeaders, $requestBody) {
        if ($response === null) {
            return null; // fallback to the default error handler
        }
        if ($statusCode === 200 || $statusCode === 202) {
            return null;
        }
        $message = $this->safe_string($response, 'message');
        $errorCode = $this->safe_string($response, 'code');
        if ($errorCode && $message) {
            $errorMessage = $this->id . ' - ' . $message;
            $erroCodeStr = (string) $errorCode;
            $this->throw_exactly_matched_exception($this->exceptions['exact'], $erroCodeStr, $errorMessage);
            $this->throw_broadly_matched_exception($this->exceptions['broad'], $message, $errorMessage);
        }
        return null;
    }
}
